VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,8.27,"Lecture eighteen. Neuromorphic computing. How a chip shaped like a brain spends energy only when something happens."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":28.352,"caps":[[0.5,7.71,"Hoglet watches the garden for hedgehogs all night."],[7.96,14.61,"Inside: a von Neumann computer, processor and memory apart."],[14.86,19.75,"A program runs step by step, in binary."],[20,26.65,"Data shuttles back and forth, and every trip costs energy."]],"warp":[[0,0],[0.5,0.4],[7.96,3.2],[14.86,6],[20,8.8],[28.352,12]]},{"dur":25.1,"caps":[[0.5,6.99,"In a neuromorphic computer, synapses store data and process it."],[7.24,12.77,"No program as such: the synapse structure sets what it does."],[13.02,18.55,"Inputs are spikes; their timing and magnitude carry information."],[18.8,24.41,"The term began in the 1980s; today it covers many brain-inspired ideas."]],"warp":[[0,0],[0.5,0.4],[7.24,3.2],[13.02,6],[18.8,9.6],[25.1,13]]},{"dur":28.282,"caps":[[0.5,6.35,"Parallel: all neurons work at once, each doing something simple."],[6.6,14.21,"Processing and memory together: faster and less energy."],[14.46,20.07,"Scalable: need a bigger network? Add more chips."],[20.32,26.49,"And the fourth: it is event driven."]],"warp":[[0,0],[0.5,0.4],[6.6,3.2],[14.46,6],[20.32,8.8],[28.282,12]]},{"dur":26.61,"caps":[[0.5,5.63,"A quiet night: a spike at only 4 of 24 moments."],[5.88,12.45,"The clocked chip works 24 times; the event-driven chip 4."],[12.7,18.63,"A busier garden: 11 spikes, 11 bursts of work."],[18.88,24.57,"No spikes, no work: it computes only when a spike arrives."]],"warp":[[0,0],[0.5,0.4],[5.88,3.2],[12.7,6],[18.88,8.8],[26.61,13]]},{"dur":28.259,"caps":[[0.5,8.19,"Graph algorithms: routing messages through a network."],[8.44,15.25,"Optimisation: constraint satisfaction, QUBO, optimal control."],[15.5,22.15,"Random walkers hop between neurons that stand for states."],[22.4,27.53,"Signal processing: steering vehicles, detecting seizures."]],"warp":[[0,0],[0.5,0.4],[8.44,3.2],[15.5,6],[22.4,8.8],[28.259,12]]},{"dur":33.413,"caps":[[0.5,8.11,"SpiNNaker: 18 ARM cores per chip, built for exploring."],[8.36,14.05,"About 16,000 neurons in real time on 1 W per chip."],[14.3,18.71,"SpiNNaker 2, in 2019, is ten times bigger."],[18.96,25.29,"IBM TrueNorth: 1 million neurons per chip, set up in Corelet."],[25.54,32.43,"NorthPole, 2023: easier, faster, efficient AI."]],"warp":[[0,0],[0.5,0.4],[8.36,3.2],[14.3,6.6],[18.96,8.8],[25.54,11.2],[33.413,14]]},{"dur":28.445,"caps":[[0.5,7.87,"Deep learning still wins on results; neuromorphic wins on energy."],[8.12,13.09,"Little hardware and software to use, and long training times."],[13.34,20.47,"No benchmark suite that tests the time aspect."],[20.72,26.25,"Networks are wired neuron by neuron, which is error prone."]],"warp":[[0,0],[0.5,0.4],[8.12,3.2],[13.34,6],[20.72,9.4],[28.445,13]]},{"dur":26.773,"caps":[[0.5,7.39,"A frame camera sends all 72 pixels, every moment."],[7.64,15.17,"An event camera's pixels spike only when brightness changes: 2."],[15.42,19.91,"Hedgehog sits still: the event camera sends nothing."],[20.16,25.61,"Sensor fusion: wake the frame camera when events appear."]],"warp":[[0,0],[0.5,0.4],[7.64,3.2],[15.42,6],[20.16,8.8],[26.773,12]]},{"dur":30.185,"caps":[[0.5,7.39,"GAs and PSO are parallel but energy hungry on normal hardware."],[7.64,14.29,"Neuromorphic heuristic units evolve candidates asynchronously."],[14.54,21.51,"No spike: a heuristic step, towards the best so far."],[21.76,25.13,"A spike: the neuron's own dynamics make a jump."],[25.38,28.83,"Promising, but still highly experimental."]],"warp":[[0,0],[0.5,0.4],[7.64,3.2],[14.54,6],[21.76,8],[25.38,9.8],[30.185,12]]},{"dur":15.001,"caps":[],"warp":[[0,0],[0.5,0.9],[6.04,2],[10.54,3.1],[15.001,9]]}]};
